int main(void)
{
    bk_init();
    media_service_init();

    if(1/*0 == ate_is_enabled()*/)   
    {
        dev_lcd_open();                   

        frame_buffer_t *bg_frame = NULL;
        frame_buffer_t *fg_frame = NULL;
        int lcd_width = dev_lcd_get_width();
        int lcd_height = dev_lcd_get_height();
        int blend_x_pos;
        int blend_y_pos;
        bk_err_t ret = BK_FAIL;
        
        bg_frame = decode_frame_malloc(lcd_width * lcd_height * 2);
        if(NULL == bg_frame)
        {
            LOGE("[%s][%d] malloc bg_frame fail\r\n", __FUNCTION__, __LINE__);
            TEST_FAIL();
            return BK_FAIL;
        }

        // 背景填充全红的背景色
        bg_frame->fmt = PIXEL_FMT_RGB565;
        bg_frame->width = lcd_width;
        bg_frame->height = lcd_height;
        
        app_display_draw_init(); // 显示绘制组件初始化
        ret = app_display_draw_fill_color(bg_frame, 0xf800, 0, 0, lcd_width, lcd_height);
        app_display_draw_deinit(); // 显示绘制组件初始化
        if(BK_OK != ret)
        {
            LOGE("[%s][%d] fill bg fail\r\n", __FUNCTION__, __LINE__);
            TEST_FAIL();
            return BK_FAIL;
        }

        // 前景使用argb8888的图片
        fg_frame = decode_frame_malloc(FG_WIDTH * FG_HEIGHT * 4);
        if(NULL == fg_frame)
        {
            LOGE("[%s][%d] malloc fg_frame fail\r\n", __FUNCTION__, __LINE__);
            TEST_FAIL();
            return BK_FAIL;
        }

        fg_frame->fmt = PIXEL_FMT_ARGB8888;
        fg_frame->width = FG_WIDTH;
        fg_frame->height = FG_HEIGHT;
        os_memcpy(fg_frame->frame, icon_map, FG_WIDTH * FG_HEIGHT * 4);

        // 融合在屏幕中间
        blend_x_pos = (lcd_width - FG_WIDTH) / 2;
        blend_y_pos = (lcd_height - FG_HEIGHT) / 2;

        app_display_draw_init();     // 显示绘制组件初始化
        ret = app_display_draw_blend(bg_frame, fg_frame, blend_x_pos, blend_y_pos);
        app_display_draw_deinit();   // 显示绘制组件反初始化
        if(BK_OK != ret)
        {
            LOGE("[%s][%d] blend fail\r\n", __FUNCTION__, __LINE__);
            TEST_FAIL();
            return BK_FAIL;
        }

        dev_lcd_flush(bg_frame, display_free_callback);   

        dev_lcd_backlight_ctrl(100);       

        TEST_PASS();
    }

    return 0;
}
